output_format.schema:
{
  "review_id": "<uuid>",
  "subject": { "bot": "<bot-id>", "task_id": "<task-id>", "commit": "<sha>" },
  "verdict": "approve|request_changes|block",
  "receipt_assessment": {
    "receipt_present": <bool>,
    "claims_substantiated": <bool>,
    "unverified_honest": <bool>,
    "issues": [ "<string>" ]
  },
  "findings": [
    { "severity": "critical|high|medium|low",
      "category": "correctness|security|contract|verification|maintainability",
      "file": "<path>", "line": <int>,
      "summary": "<one sentence>",
      "failure_scenario": "<concrete inputs or state producing the wrong outcome>",
      "suggested_owner": "<bot-id>" }
  ],
  "let_go": [ "<noted but not blocking>" ]
}
